{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver definitionen korrekt og nævner omkring ét år. Men sidste sætning er for kategorisk: den uddannelsessøgende 'skal have oplevet symptomer ... i mindst et år' for at være berettiget. Kilden siger 'som udgangspunkt', og tiden alene afgør ikke varigheden. Det er en væsentlig fejl efter rubrikken, som kalder det en materiel fejl, hvis et år fremstilles som en ubetinget betingelse. Svaret nævner heller ikke muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Der mangler to kritiske elementer. Svaret siger ikke, at varighed er en grundlæggende forudsætning, der vedrører funktionsnedsættelsens art og grad. Det nævner heller ikke, at tidsbegrænset tillæg kan gives, når varighed er sandsynliggjort men ikke endeligt fastslået. Definitionen og étårsreglen er med."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: hvornår en nedsættelse er varig, og hvad der gælder, hvis den ikke er varig fra begyndelsen. Det indeholder ingen irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bestemmelse eller vejledning. Det har kun almindelig tekst."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ingen kilde i svaret, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen kilde i svaret, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en absolut betingelse om, at den uddannelsessøgende 'skal' have oplevet symptomer i mindst et år for at være berettiget. Passagen siger kun 'som udgangspunkt', så betingelsen er ikke støttet i denne absolutte form."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer 'omkring et år' og 'kan vurderes'. Det udelader dog 'som udgangspunkt' i den afsluttende sætning om mindst et år og i definitionen. Det udelader også forbeholdet om, at tidsforløbet alene ikke afgør varigheden, og at tidsbegrænset tillæg kan gives ved sandsynliggjort varighed."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinene hænger sammen. Svaret giver definition, derefter étårsvurderingen og til sidst en konsekvens. Konklusionen følger af svarets egne trin, selvom den er for kategorisk."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Skal have oplevet symptomer ... i mindst et år' gør et udgangspunkt til en absolut regel. Definitionen i første sætning mangler også 'som udgangspunkt'. Det ændrer modaliteten i forhold til kilden."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret forklarer, hvad en varig funktionsnedsættelse er. Det siger ikke eksplicit, at varighed er en grundlæggende forudsætning for handicaptillæg."
    },
    "A12": {
      "label": "partial",
      "reason": "Svaret dækker, at en ikke-varig tilstand kan vurderes varig efter omkring et år, og at symptomer skal have varet mindst et år før ansøgning. Det udelader 'som udgangspunkt' og udgangspunktet om, at man ikke er berettiget, hvis tilstanden ikke fra debut er varig eller kronisk. Det gør formuleringen for absolut."
    }
  },
  "overall_notes": "Svaret er kort og i store træk korrekt om definitionen og étårsvurderingen. Det gør dog étårskravet absolut og fjerner 'som udgangspunkt'. Det mangler også forudsætningen om art og grad og muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed. Der er ingen kildeangivelse, så C04 er not_met, og C05 og C06 er not_assessable."
}

